import {
  Group,
  Mesh,
  MeshStandardMaterial,
  MeshBasicMaterial,
  CylinderGeometry,
  PlaneGeometry,
  Float32BufferAttribute,
  Color,
  Object3D,
} from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root group
  const root = new Group();
  const pos = config.position ?? [0, 0, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];
  root.position.set(pos[0], pos[1], pos[2]);
  root.rotation.set(rot[0], rot[1], rot[2]);
  root.scale.set(scl[0], scl[1], scl[2]);

  // Load watch GLB
  const glb = ctx.glbLoader.load(config.assets?.meshUrl || '/prism-mock/orrery/meshes/watch.glb');
  const watch = glb.scene.clone();
  root.add(watch);

  // Plinth
  const plinthGeom = new CylinderGeometry(1.4, 1.4, 0.25, 32);
  const plinthMat = new MeshStandardMaterial({
    color: new Color('#14141a'),
    metalness: 0.3,
    roughness: 0.7,
  });
  const plinth = new Mesh(plinthGeom, plinthMat);
  // top face at y = -1.1 => center y = -1.1 + height/2
  plinth.position.set(0, -1.1 + 0.125, 0);
  root.add(plinth);

  // Backdrop gradient plane
  const backdropGeom = new PlaneGeometry(7, 6, 1, 1);
  const bottomCol = new Color('#0b0b10');
  const topCol = new Color('#16161d');
  const colors = [];
  for (let i = 0; i < backdropGeom.attributes.position.count; i++) {
    const y = backdropGeom.attributes.position.getY(i); // range -3 .. 3
    const t = (y + 3) / 6; // 0 .. 1
    const col = bottomCol.clone().lerp(topCol, t);
    colors.push(col.r, col.g, col.b);
  }
  backdropGeom.setAttribute('color', new Float32BufferAttribute(colors, 3));
  const backdropMat = new MeshStandardMaterial({
    vertexColors: true,
    metalness: 0,
    roughness: 1,
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // Contact shadow
  const shadowGeom = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.55,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.1, 0);
  root.add(shadow);

  // Text creation helper
  const createdTexts = [];
  const createText = (content, style, yOffset) => {
    // Assume ctx.text.createTextMesh exists and returns an Object3D
    const textMesh = ctx.text.createTextMesh(content, {
      fontFamily: style.family,
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: '#e8ecf2',
    }, ctx.fontAtlas);
    textMesh.position.set(0, yOffset, 0);
    root.add(textMesh);
    createdTexts.push(textMesh);
  };

  // Text positions (baseline offsets)
  createText(
    config.textContent?.headline || 'Calibre NA-01',
    { family: 'Lora', fontSize: 68, fontWeight: 600, letterSpacing: -0.005, lineHeight: 1.1 },
    -1.5
  );
  createText(
    config.textContent?.body || 'Machined in-house. 41 mm. Grade 5 titanium.',
    { family: 'JetBrains Mono', fontSize: 26, fontWeight: 400, letterSpacing: 0, lineHeight: 1.5 },
    -1.8
  );
  createText(
    config.textContent?.caption || 'FROM 4200 USD / SHIPS IN 21 DAYS',
    { family: 'JetBrains Mono', fontSize: 18, fontWeight: 400, letterSpacing: 0.08, lineHeight: 1.4 },
    -2.0
  );

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // Cleanup
  const timelines = []; // placeholder for any GSAP timelines we might start later

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose watch meshes
    watch.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material?.dispose();
        }
      }
    });

    // Dispose other meshes
    plinth.geometry.dispose();
    plinthMat.dispose();
    backdrop.geometry.dispose();
    backdropMat.dispose();
    shadow.geometry.dispose();
    shadowMat.dispose();

    // Dispose created text meshes
    createdTexts.forEach((txt) => {
      txt.traverse((obj) => {
        if (obj.isMesh) {
          obj.geometry?.dispose();
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material?.dispose();
          }
        }
      });
    });

    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
